// ====================================================================
// GPS SOCIAL SPY — NORMALIZE & TRUST LAYER v9
// Corrected production version: Reels + Videos + Images + Albums + Text
// Key fix: Reels are matched by facebookUrl/inputUrl/pageName/user.name,
// not only by reel URL. No real scraped post is silently dropped.
// ====================================================================

const BRAND_MAP = [
  { brand: 'Amazing Track Company Limited', url: 'facebook.com/amazingtrack', aliases: ['amazingtrack', 'Amazing Track Company Limited'] },
  { brand: 'Gonlolo GPS Myanmar-GPS ပညာရှင်', url: 'facebook.com/GonloloGPS', aliases: ['GonloloGPS', 'Gonlolo GPS Myanmar', 'Gonlolo GPS Myanmar-GPS ပညာရှင်'] },
  { brand: 'GPS tracker', url: 'facebook.com/gpstracker.mm', aliases: ['gpstracker.mm', 'GPS tracker'] },
  { brand: 'Gps Burma', url: 'facebook.com/gpsburma25', aliases: ['gpsburma25', 'Gps Burma', 'GPS Burma'] },
  { brand: 'GoSafe GPS ခြေရာခံစနစ်', url: 'facebook.com/gosafegpstracker', aliases: ['gosafegpstracker', 'GoSafe GPS'] },
  { brand: 'Idea Shop', url: 'facebook.com/myomakhin2019', aliases: ['myomakhin2019', 'Idea Shop'] },
  { brand: 'Tracker Star GPS System', url: 'facebook.com/TrackerStarGPS', aliases: ['TrackerStarGPS', 'Tracker Star GPS System'] },
  { brand: 'Gps Service Myanmar', url: 'facebook.com/GpsServiceMyanmar', aliases: ['GpsServiceMyanmar', 'Gps Service Myanmar', 'GPS Service Myanmar'] },
  { brand: 'Track Man Myanmar', url: 'facebook.com/gpstrackmanmyanmar', aliases: ['gpstrackmanmyanmar', 'Track Man Myanmar'] },
  { brand: 'Sinotrack GPS Tracker Myanmar', url: 'facebook.com/sinotrackgpsmyanmar', aliases: ['sinotrackgpsmyanmar', 'Sinotrack GPS Tracker Myanmar'] },
  { brand: 'Happy GPS Myanmar', url: 'facebook.com/HappyGPSMM', aliases: ['HappyGPSMM', 'Happy GPS Myanmar', 'happygpsmyanmar'] },
  { brand: 'Doe Soh GPS Tracker', url: 'facebook.com/Doesohgpstracker', aliases: ['Doesohgpstracker', 'Doe Soh GPS Tracker'] },
  { brand: 'AGB Smart Track', url: 'facebook.com/agbsmarttrack', aliases: ['agbsmarttrack', 'AGB Smart Track', 'AGBSmartTrack'] },
  { brand: 'Myanmar GPS Solution', url: 'facebook.com/gpsblackboxmyanmar', aliases: ['gpsblackboxmyanmar', 'Myanmar GPS Solution'] },
  { brand: 'FAST GPS & Electronic', url: 'facebook.com/profile.php?id=61551864023705', aliases: ['61551864023705', 'FAST GPS', 'FAST GPS & Electronic'] }
];

const CUSTOMER_KEYWORDS = [
  { name: 'Dong Peng Plastic Mould Mechine & Trading Co.,Ltd', tokens: ['dong peng', 'plastic mould', 'dongpeng'] },
  { name: 'Octelle Co.,Ltd', tokens: ['octelle'] },
  { name: 'Iceland', tokens: ['iceland'] },
  { name: 'Suzuki Ciaz', tokens: ['suzuki ciaz', 'ciaz'] }
];

function safeText(v) { return String(v ?? ''); }
function safeLower(v) { return safeText(v).toLowerCase(); }

function toNumber(v) {
  if (v === null || v === undefined || v === '' || v === '–') return 0;
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const s = String(v).replace(/,/g, '').trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function firstValue(...values) {
  for (const v of values) {
    if (v !== null && v !== undefined && v !== '') return v;
  }
  return null;
}

function normalizeUrlText(v) {
  return safeLower(v).replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
}

function getPostUrl(post) {
  return firstValue(post.url, post.postUrl, post.facebookUrl, post.topLevelUrl, post.permalinkUrl, post.link, post.inputUrl);
}

function getText(post) {
  return firstValue(post.text, post.caption, post.message, post.description, post.title, post.captionText) || '-';
}

function getViews(post) {
  return toNumber(firstValue(
    post.viewsCount,
    post.videoViewCount,
    post.videoPostViewCount,
    post.viewCount,
    post.views,
    post.playCount,
    post.plays,
    post.videoPlayCount,
    post.reelPlayCount,
    post.watchCount
  ));
}

function collectDeepStrings(value, limit = 250) {
  const out = [];
  const seen = new Set();
  function walk(v) {
    if (out.length >= limit) return;
    if (v === null || v === undefined) return;
    if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
      const s = String(v);
      if (s && s.length <= 500 && !seen.has(s)) {
        seen.add(s);
        out.push(s);
      }
      return;
    }
    if (Array.isArray(v)) {
      for (const x of v) walk(x);
      return;
    }
    if (typeof v === 'object') {
      for (const k of Object.keys(v)) {
        if (['profilePic', 'thumbnail', 'uri', 'image'].includes(k) && out.length > limit / 2) continue;
        walk(v[k]);
      }
    }
  }
  walk(value);
  return out.join(' ');
}

function resolveBrandName(post) {
  const targetUrl = getPostUrl(post);
  const haystack = normalizeUrlText([
    targetUrl,
    post.inputUrl,
    post.facebookUrl,
    post.topLevelUrl,
    post.pageName,
    post.facebookId,
    post.user?.id,
    post.user?.name,
    post.user?.profileUrl,
    post.owner?.id,
    collectDeepStrings(post.textReferences || [])
  ].filter(Boolean).join(' '));

  for (const b of BRAND_MAP) {
    const url = normalizeUrlText(b.url);
    const slug = url.replace('facebook.com/', '');
    const aliases = [b.brand, b.url, slug, ...(b.aliases || [])].map(normalizeUrlText).filter(Boolean);
    if (aliases.some(a => a && haystack.includes(a))) return b.brand;
  }
  return null;
}

function countNestedMedia(post) {
  const ids = new Set();
  let count = 0;
  function noteMedia(m) {
    if (!m || typeof m !== 'object') return;
    const typename = safeLower(m.__typename || m.__isMedia || m.__isNode || m.type);
    const hasMedia = typename.includes('photo') || typename.includes('video') || typename.includes('image') || m.image || m.thumbnail || m.url || m.playable_url;
    if (!hasMedia) return;
    const id = m.id || m.url || m.thumbnail || JSON.stringify(m).slice(0, 80);
    if (!ids.has(id)) {
      ids.add(id);
      count++;
    }
  }
  function walk(v) {
    if (!v || typeof v !== 'object') return;
    if (Array.isArray(v)) { v.forEach(walk); return; }
    noteMedia(v.media || v);
    for (const k of Object.keys(v)) {
      if (['owner', 'user', 'profilePic'].includes(k)) continue;
      walk(v[k]);
    }
  }
  walk(post.media);
  walk(post.images);
  walk(post.photos);
  walk(post.attachments);
  return count;
}

function getMediaCount(post) {
  const directCounts = [post.media, post.images, post.photos, post.attachments]
    .filter(Array.isArray)
    .map(a => a.length);
  return Math.max(0, ...directCounts, countNestedMedia(post));
}

function detectPostType(post) {
  const targetUrl = getPostUrl(post);
  const url = safeLower(targetUrl);
  const deep = safeLower(collectDeepStrings(post, 400));
  const rawType = safeLower(firstValue(post.type, post.mediaType, post.__typename, post.postType));
  const mediaCount = getMediaCount(post);
  const views = getViews(post);

  if (url.includes('/reel/') || url.includes('/reels/') || rawType.includes('reel') || deep.includes('reel')) return 'Reel';

  const hasVideoSignal =
    post.isVideo === true ||
    url.includes('/videos/') ||
    url.includes('/watch/') ||
    rawType.includes('video') ||
    deep.includes('__typename video') ||
    deep.includes('is_playable true') ||
    !!post.video || !!post.videoUrl || !!post.video_url || !!post.videoThumbnail ||
    views > 0;
  if (hasVideoSignal) return 'Video';

  const hasSharedSignal = !!post.sharedPost || !!post.sharedUrl || !!post.sharedFrom || rawType.includes('share') || url.includes('/share/');
  if (hasSharedSignal) return 'Shared Post';

  if (mediaCount > 1) return 'Multi Image / Album';

  const hasImageSignal =
    mediaCount === 1 || !!post.image || !!post.imageUrl || !!post.thumbnail || !!post.photoUrl ||
    rawType.includes('photo') || rawType.includes('image') || url.includes('/photos/') || url.includes('/photo/');
  if (hasImageSignal) return 'Image';

  return 'Text';
}

function formatMyanmarDate(d) {
  const date = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Yangon', day: '2-digit', month: 'short', year: 'numeric' }).format(d);
  const time = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Yangon', hour: '2-digit', minute: '2-digit', hour12: true }).format(d);
  return `${date}, ${time}`;
}

function timeBucket(hour) {
  if (hour >= 6 && hour < 10) return 'Morning (6-10 AM)';
  if (hour >= 10 && hour < 14) return 'Midday (10 AM-2 PM)';
  if (hour >= 14 && hour < 18) return 'Afternoon (2-6 PM)';
  if (hour >= 18 && hour < 22) return 'Evening (6-10 PM)';
  return 'Late Night (10 PM-6 AM)';
}

function getYangonDayType(d) {
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Yangon', weekday: 'short' }).format(d);
  return (dayStr === 'Sat' || dayStr === 'Sun') ? 'Weekend' : 'Weekday';
}

function extractCustomerSegment(content) {
  const lower = safeLower(content);
  if (lower.includes('လုပ်ငန်းသုံး') || lower.includes('ကုမ္ပဏီ') || lower.includes('ယာဉ်အုပ်စု') || lower.includes('ကုမ္ပဏီသုံး') || lower.includes('fleet') || lower.includes('business') || lower.includes('company')) return 'B2B (Enterprise/Fleet)';
  if (lower.includes('အိမ်သုံး') || lower.includes('ကိုယ်ပိုင်') || lower.includes('ဆိုင်ကယ်') || lower.includes('private') || lower.includes('personal')) return 'B2C (Personal/Consumer)';
  return 'General / Branding';
}

function extractCustomerMention(content) {
  const lower = safeLower(content);
  for (const cust of CUSTOMER_KEYWORDS) {
    if (cust.tokens.some(token => lower.includes(token))) return cust.name;
  }
  return '–';
}

function looksLikePostRecord(post) {
  const url = safeLower(getPostUrl(post));
  return Boolean(
    post.postId || post.time || post.timestamp || post.createdAt || post.publishTime ||
    url.includes('/posts/') || url.includes('/reel/') || url.includes('/reels/') || url.includes('/videos/') ||
    post.isVideo || post.media || post.images || post.photos || getText(post) !== '-'
  );
}

const items = $input.all();
let posts = [];
let reviewRecords = [];
let detectedBrandsSet = new Set();
let rawRecordCount = 0;

for (const item of items) {
  let dataPayload = [];
  if (Array.isArray(item.json)) dataPayload = item.json;
  else if (Array.isArray(item.json?.data)) dataPayload = item.json.data;
  else if (item.json && typeof item.json === 'object') dataPayload = [item.json];

  for (const post of dataPayload) {
    rawRecordCount++;
    try {
      if (!looksLikePostRecord(post)) {
        reviewRecords.push({ reason: 'Non-post / page-level record', url: getPostUrl(post) || post.inputUrl || 'No URL', sample: getText(post).slice(0, 120) });
        continue;
      }

      const targetUrl = getPostUrl(post);
      const resolvedBrand = resolveBrandName(post) || 'Unknown / Needs Review';
      if (resolvedBrand !== 'Unknown / Needs Review') detectedBrandsSet.add(resolvedBrand);

      const reactions = toNumber(firstValue(post.likes, post.reactions, post.reactionsCount, post.likesCount, post.reactionLikeCount));
      const comments = toNumber(firstValue(post.comments, post.commentsCount));
      const shares = toNumber(firstValue(post.shares, post.sharesCount));
      const engagement = reactions + comments + shares;
      const rawTime = firstValue(post.time, post.timestamp, post.date, post.createdAt, post.publishTime);
      const dateObj = rawTime ? new Date(rawTime) : null;
      const hasValidDate = dateObj && !isNaN(dateObj);
      const type = detectPostType(post);
      const views = getViews(post);
      let content = getText(post);
      const fullContent = content;
      if (content.length > 250) content = content.slice(0, 250) + '...';

      const hour = hasValidDate ? parseInt(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Yangon', hour: 'numeric', hour12: false }).format(dateObj), 10) : null;

      const normalized = {
        brand: resolvedBrand,
        page: resolvedBrand !== 'Unknown / Needs Review' ? resolvedBrand : (post.pageName || post.user?.name || 'Unknown'),
        type,
        content,
        reactions,
        comments,
        shares,
        engagement,
        reach: views > 0 ? views : '–',
        postedAt: hasValidDate ? formatMyanmarDate(dateObj) : 'Missing Time',
        timestamp: hasValidDate ? dateObj.getTime() : 0,
        hour,
        timeBucket: hasValidDate ? timeBucket(hour) : 'Missing Time',
        dayType: hasValidDate ? getYangonDayType(dateObj) : 'Missing Time',
        customerSegment: extractCustomerSegment(fullContent),
        customerMentioned: extractCustomerMention(fullContent),
        mediaCount: getMediaCount(post),
        rawType: firstValue(post.type, post.mediaType, post.__typename, post.postType) || '–',
        pageName: post.pageName || '–',
        facebookUrl: post.facebookUrl || '–',
        inputUrl: post.inputUrl || '–',
        link: targetUrl || '#',
        reviewStatus: resolvedBrand === 'Unknown / Needs Review' || !hasValidDate ? 'Needs Review' : 'Clean'
      };

      posts.push(normalized);

      if (normalized.reviewStatus === 'Needs Review') {
        reviewRecords.push({
          reason: resolvedBrand === 'Unknown / Needs Review' ? 'Brand not matched' : 'Missing/invalid time',
          brand: normalized.brand,
          pageName: normalized.pageName,
          type: normalized.type,
          url: normalized.link,
          inputUrl: normalized.inputUrl,
          content: normalized.content
        });
      }
    } catch (e) {
      reviewRecords.push({ reason: 'Processing error', message: e.message, url: getPostUrl(post) || post.inputUrl || 'No URL' });
    }
  }
}

// De-duplicate by URL/postId when Apify returns duplicates. Keep the richer record.
const byKey = new Map();
for (const p of posts) {
  const key = p.link && p.link !== '#' ? p.link : `${p.brand}|${p.timestamp}|${p.content.slice(0, 60)}`;
  const existing = byKey.get(key);
  if (!existing || (toNumber(p.reach) + p.engagement + p.mediaCount) > (toNumber(existing.reach) + existing.engagement + existing.mediaCount)) {
    byKey.set(key, p);
  }
}
posts = Array.from(byKey.values());

const cleanPosts = posts.filter(p => p.reviewStatus === 'Clean');

const pageSummary = {};
for (const p of posts) {
  if (!pageSummary[p.brand]) pageSummary[p.brand] = { brand: p.brand, posts: 0, reactions: 0, comments: 0, shares: 0, engagement: 0, reach: 0 };
  pageSummary[p.brand].posts += 1;
  pageSummary[p.brand].reactions += p.reactions;
  pageSummary[p.brand].comments += p.comments;
  pageSummary[p.brand].shares += p.shares;
  pageSummary[p.brand].engagement += p.engagement;
  pageSummary[p.brand].reach += toNumber(p.reach);
}

const brands = Object.values(pageSummary).map(b => ({ ...b, avgEngagementPerPost: b.posts ? Math.round(b.engagement / b.posts) : 0 })).sort((a, b) => b.engagement - a.engagement);

const masterBrandNames = BRAND_MAP.map(b => b.brand);
const silentBrands = masterBrandNames.filter(b => !detectedBrandsSet.has(b));

const summarize = (arr, keyFn, initFn, addFn) => {
  const o = {};
  for (const p of arr) {
    const key = keyFn(p);
    if (!o[key]) o[key] = initFn(key, p);
    addFn(o[key], p);
  }
  return Object.values(o);
};

const times = summarize(posts.filter(p => p.timestamp > 0), p => `${p.dayType} | ${p.timeBucket}`, key => ({ label: key, posts: 0, engagement: 0 }), (s, p) => { s.posts++; s.engagement += p.engagement; }).sort((a, b) => b.engagement - a.engagement);
const types = summarize(posts, p => p.type, key => ({ type: key, posts: 0, engagement: 0, reach: 0 }), (s, p) => { s.posts++; s.engagement += p.engagement; s.reach += toNumber(p.reach); }).sort((a, b) => b.engagement - a.engagement);

const segmentMap = {};
for (const p of posts) {
  if (!segmentMap[p.customerSegment]) segmentMap[p.customerSegment] = { segment: p.customerSegment, count: 0, brandsSet: new Set() };
  segmentMap[p.customerSegment].count++;
  segmentMap[p.customerSegment].brandsSet.add(p.brand);
}
const segments = Object.values(segmentMap).map(s => ({ segment: s.segment, count: s.count, brands: Array.from(s.brandsSet).join(', ') })).sort((a, b) => b.count - a.count);

const topPosts = [...posts].sort((a, b) => b.engagement - a.engagement).slice(0, 3);

let weekRange = 'Current Week';
const dated = posts.filter(p => p.timestamp > 0).map(p => p.timestamp).sort((a, b) => a - b);
if (dated.length > 0) {
  const start = new Date(dated[0]).toLocaleDateString('en-GB', { day: '2-digit', month: 'short' });
  const end = new Date(dated[dated.length - 1]).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  weekRange = `${start} - ${end}`;
}

return [{
  json: {
    meta: {
      rawRecordCount,
      totalPosts: posts.length,
      cleanPosts: cleanPosts.length,
      reviewCount: reviewRecords.length,
      totalBrands: brands.filter(b => b.brand !== 'Unknown / Needs Review').length,
      silentBrands,
      generatedAt: new Date().toISOString(),
      timezone: 'Asia/Yangon',
      engagementFormula: 'Reactions + Comments + Shares',
      weekRange,
      note: 'v9 includes Reels by matching brand from facebookUrl, inputUrl, pageName, user.name, aliases, and post URL. No real scraped post is silently dropped.'
    },
    posts,
    reviewRecords: reviewRecords.slice(0, 50),
    brands,
    times,
    types,
    segments,
    topPosts
  }
}];

// ====================================================================
// GPS SOCIAL SPY — EMAIL BUILDER (PRODUCTION v7.5 - FIXED NO-OVERLAP)
// ====================================================================

const data = $input.first().json;
const { meta, posts, brands, times, types, segments, topPosts } = data;

const totalEngagement = brands.reduce((s, b) => s + b.engagement, 0);

const sortedBrands = brands.map(b => ({
  ...b,
  percent: totalEngagement ? Math.round((b.engagement / totalEngagement) * 100) : 0
}));

const top5 = sortedBrands.slice(0, 5);
const rest = sortedBrands.slice(5);

// ── 🎨 Premium Design Tokens ────────────────────────────────────────
const HERO_BG    = '#0f172a'; 
const ACCENT_GOLD = '#f59e0b'; 
const ACCENT_BLUE = '#2563eb'; 
const TEXT_MAIN  = '#1e293b'; 
const TEXT_SUB   = '#475569'; 
const TEXT_MUTED = '#94a3b8'; 
const BORDER     = '#e2e8f0'; 
const ROW_ALT    = '#f8fafc'; 
const RED        = '#ef4444'; 

// ── 🛠️ Mobile-Safe Table Cell Helpers (Strict Non-Breaking Layout) ──
const td = (v, opts = {}) => {
  const align  = opts.align  || 'left';
  const bold   = opts.bold   ? 'font-weight:700;' : '';
  const color  = opts.color  ? `color:${opts.color};` : `color:${TEXT_MAIN};`;
  const width  = opts.width  ? `width:${opts.width}; max-width:${opts.width};` : '';

  return `<td style="padding:12px 14px; border-bottom:1px solid ${BORDER}; font-size:13px; line-height:1.5; ${color}${bold}${width} text-align:${align}; vertical-align:middle; white-space:normal; overflow:visible;">${v}</td>`;
};

const th = (v, align = 'left', width = '') => {
  const widthStr = width ? `width:${width}; max-width:${width};` : '';
  return `<th style="padding:12px 14px; background:#f1f5f9; font-size:11px; font-weight:700; color:${TEXT_SUB}; text-align:${align}; border-bottom:2px solid ${BORDER}; letter-spacing:0.8px; text-transform:uppercase; ${widthStr}">${v}</th>`;
};

const section = (emoji, title) =>
  `<h2 style="font-size:16px; font-weight:700; color:${HERO_BG}; margin:36px 0 16px; padding-bottom:10px; border-bottom:2px solid ${ACCENT_BLUE};">${emoji}&nbsp; ${title}</h2>`;

const divider =
  `<div style="height:1px; background:${BORDER}; margin:32px 0; clear:both;"></div>`;

// 🎨 Colorful Badges Generator with Safe-Wrap Container
const getSegmentBadge = (segment) => {
  if (!segment || segment === '–') return '<span style="color:#cbd5e1;">–</span>';
  let bg = '#f1f5f9';
  let color = '#475569';
  if (segment.includes('B2B')) { bg = '#dbeafe'; color = '#1e40af'; }
  else if (segment.includes('B2C')) { bg = '#dcfce7'; color = '#166534'; }
  return `<div style="display:block; margin-bottom:4px;"><span style="display:inline-block; padding:5px 10px; border-radius:20px; font-size:11px; font-weight:700; background-color:${bg}; color:${color}; white-space:nowrap; max-width:100%; text-overflow:ellipsis; overflow:hidden;">${segment}</span></div>`;
};

const getCustomerBadge = (name) => {
  if (!name || name === '–') return '<span style="color:#cbd5e1;">–</span>';
  return `<div style="display:block; margin-top:4px;"><span style="display:inline-block; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700; background-color:#f3e8ff; color:#6b21a8; border:1px solid #e9d5ff; white-space:normal; word-break:break-word; max-width:100%;">🏢 ${name}</span></div>`;
};

// ── Weekly Observations ───────────────────────────────────────────
const topBrand   = brands[0]?.brand       || null;
const topContent = types[0]?.type         || null;
const topSegment = segments[0]?.segment  || null;

const obs = [];
obs.push(`${meta.totalPosts} brand post${meta.totalPosts !== 1 ? 's' : ''} detected during this reporting period.`);
obs.push(`${meta.totalBrands} brand${meta.totalBrands !== 1 ? 's' : ''} showed posting activity this week.`);
if (topBrand)   obs.push(`<b>${topBrand}</b> generated the highest observed engagement among monitored brands.`);
if (topContent) obs.push(`${topContent} posts represented the most frequently observed content type.`);
if (topSegment) obs.push(`${topSegment} was the most frequently detected customer segment signal.`);

const obsBullets = obs.slice(0, 5)
  .map(o => `<li style="margin-bottom:10px; font-size:13px; color:${TEXT_MAIN}; line-height:1.6;">${o}</li>`)
  .join('');

// ── Top 5 brand rows ──────────────────────────────────────────────
const top5Rows = top5.map((b, i) => {
  const colors = ['#f59e0b', '#3b82f6', '#10b981', '#6366f1', '#8b5cf6'];
  const rankColor = colors[i] || ACCENT_BLUE;
  return `
<li style="margin-bottom:16px; font-size:13px; line-height:1.7; list-style:none; position:relative; padding-left:10px;">
  <span style="color:${rankColor}; font-weight:800; font-size:16px;">#${i+1}</span> &nbsp;
  <b style="color:${HERO_BG}; font-size:14px;">${b.brand}</b>
  &nbsp;<span style="background:${rankColor}15; color:${rankColor}; padding:2px 6px; border-radius:4px; font-weight:700; font-size:12px;">${b.engagement.toLocaleString()} Engagement</span>
  &nbsp;<span style="color:${TEXT_MUTED}; font-size:12px;">(${b.percent}% of market share)</span><br>
  <div style="color:${TEXT_SUB}; font-size:12px; margin-top:4px; padding-left:26px;">
    Total Posts: <b style="color:${TEXT_MAIN};">${b.posts}</b> &nbsp;·&nbsp;
    Avg. Engagement/Post: <b style="color:${ACCENT_BLUE};">${b.avgEngagementPerPost.toLocaleString()}</b>
  </div>
</li>`;
}).join('');

