const MMT_OFFSET_MS = 390 * 60 * 1000; // UTC+6:30

function toNumber(v) {
  if (v === null || v === undefined || v === '' || v === '–') return 0;
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const cleaned = String(v).replace(/,/g, '').trim();
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : 0;
}

function firstValue(...values) {
  for (const v of values) {
    if (v !== null && v !== undefined && v !== '') return v;
  }
  return null;
}

function normalizeKey(str) {
  if (!str) return '';
  return String(str).toLowerCase().replace(/^@/, '').replace(/[^a-z0-9]/g, '');
}

function safeText(v) {
  return String(v || '').trim();
}

function getMMTHour(unixMs) {
  return new Date(unixMs + MMT_OFFSET_MS).getUTCHours();
}

function formatMMT(unixSec) {
  if (!unixSec) return 'Missing Time';
  const d = new Date(unixSec * 1000 + MMT_OFFSET_MS);
  if (isNaN(d)) return 'Invalid Time';
  const day = String(d.getUTCDate()).padStart(2, '0');
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const mon = months[d.getUTCMonth()];
  const yr = d.getUTCFullYear();
  const hh = d.getUTCHours();
  const mm = String(d.getUTCMinutes()).padStart(2, '0');
  const ampm = hh >= 12 ? 'PM' : 'AM';
  const h12 = hh % 12 || 12;
  return `${day} ${mon} ${yr}, ${h12}:${mm} ${ampm} MMT`;
}

function timeBucket(mmtHour) {
  if (mmtHour === null || mmtHour === undefined || isNaN(mmtHour)) return 'Missing Time';
  if (mmtHour >= 6  && mmtHour < 10) return 'Morning (6-10 AM)';
  if (mmtHour >= 10 && mmtHour < 14) return 'Midday (10 AM-2 PM)';
  if (mmtHour >= 14 && mmtHour < 18) return 'Afternoon (2-6 PM)';
  if (mmtHour >= 18 && mmtHour < 22) return 'Evening (6-10 PM)';
  return 'Late Night (10 PM-6 AM)';
}

function detectTheme(text) {
  if (!text) return 'General';
  const t = String(text).toLowerCase();
  if (/ဝန်ထမ်း|field|manager|လုပ်ငန်းရှင်|ကုန်ကား|fleet|b2b|business|company/.test(t)) return 'Fleet / B2B';
  if (/ကလေး|မိဘ|ခွေး|ကြောင်|pet|child|family|smart tag|personal/.test(t)) return 'Family / Personal';
  if (/ခိုး|ပျောက်|steal|theft|waterproof|anti|လုံခြုံ|security/.test(t)) return 'Theft / Security';
  if (/warranty|4g|2g|real.?time|geo.?fence|playback|vl103|gs900|spec|feature/.test(t)) return 'Product Spec';
  if (/မန့်|comment|mention|ရှိလား|\?|😁|humor|voiceeffect|duet|stitch/.test(t)) return 'Engagement / Humor';
  return 'General';
}

