function getInputHandle(data) {
  const input = firstValue(data.input, data.inputUrl, data.url, data.webVideoUrl, data.authorMeta?.name, data.authorMeta?.nickName);
  const s = String(input || '').trim();
  const atMatch = s.match(/@([A-Za-z0-9._-]+)/);
  if (atMatch) return atMatch[1];
  const profileMatch = s.match(/tiktok\.com\/([^/]+)/i);
  if (profileMatch) return profileMatch[1].replace('@', '');
  return s.replace('@', '');
}

function resolveBrand(data) {
  const possibleKeys = [
    data?.authorMeta?.name,
    data?.authorMeta?.nickName,
    data?.authorMeta?.uniqueId,
    data?.author?.uniqueId,
    data?.author?.nickname,
    data?.input,
    data?.inputUrl,
    getInputHandle(data)
  ].filter(Boolean).map(normalizeKey).filter(Boolean);

  for (const key of possibleKeys) {
    if (brandMap[key]) return brandMap[key];
  }

  const nick = safeText(data?.authorMeta?.nickName || data?.author?.nickname);
  const name = safeText(data?.authorMeta?.name || data?.author?.uniqueId || getInputHandle(data));
  return nick || name || 'Unknown / Needs Review';
}

function detectTikTokPostType(data) {
  const textBlob = [
    data.type,
    data.itemType,
    data.mediaType,
    data.awemeType,
    data.createType,
    data.videoMeta?.format,
    data.videoMeta?.codecType
  ].filter(Boolean).join(' ').toLowerCase();

  const imageArrays = [
    data.slideshowImageUrls,
    data.imagePost?.images,
    data.imagePost,
    data.images,
    data.imageUrls,
    data.photos,
    data.photoUrls
  ];
  const hasImageArray = imageArrays.some(v => Array.isArray(v) && v.length > 0);

  if (data.isSlideshow === true || data.is_slideshow === true || hasImageArray || textBlob.includes('slideshow') || textBlob.includes('photo')) {
    return 'Slideshow / Photo Post';
  }

  if (data.isLive === true || data.live === true || textBlob.includes('live')) {
    return 'Live';
  }

  const hasVideoSignal = !!(
    data.videoMeta || data.videoUrl || data.webVideoUrl || data.videoUrlNoWaterMark ||
    data.videoUrlNoWaterMark || data.playAddr || data.downloadAddr || data.video?.playAddr ||
    data.id || data.playCount !== undefined
  );

  if (hasVideoSignal) return 'Video';
  return 'Unknown / Needs Review';
}

