function getCreateTime(data) {
  const raw = firstValue(data.createTime, data.createTimeISO, data.createdAt, data.timestamp);
  if (!raw) return null;
  if (typeof raw === 'number') {
    // TikTok createTime is usually seconds. If it looks like ms, convert to seconds.
    return raw > 9999999999 ? Math.floor(raw / 1000) : raw;
  }
  const asNum = Number(raw);
  if (Number.isFinite(asNum)) return asNum > 9999999999 ? Math.floor(asNum / 1000) : asNum;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : null;
