      reason: 'No videos in selected period',
      raw_status: data.note,
      link: firstValue(data.url, data.inputUrl, data.input, '#')
    });
    continue;
  }

  const postId = firstValue(data.id, data.videoId, data.awemeId);
  const createTime = getCreateTime(data);

  // If it does not look like a post, keep it for review but do not pollute report metrics.
  if (!postId && !createTime && !data.playCount && !data.diggCount) {
    reviewRecords.push({
      brand_name: brand,
      profile: getInputHandle(data),
      reason: 'Non-post/profile-level record',
      raw_status: firstValue(data.note, data.error, 'No post identifiers'),
      link: firstValue(data.url, data.inputUrl, data.input, '#')
    });
    continue;
  }

  seenBrands.add(brand);

  const views    = toNumber(firstValue(data.playCount, data.views, data.viewCount));
  const likes    = toNumber(firstValue(data.diggCount, data.likes, data.likeCount));
  const comments = toNumber(firstValue(data.commentCount, data.comments));
  const shares   = toNumber(firstValue(data.shareCount, data.shares));
  const saves    = toNumber(firstValue(data.collectCount, data.saveCount, data.saves, data.bookmarkCount));
  const engagement = likes + comments + shares + saves;

  const unixMs = createTime ? createTime * 1000 : 0;
  const mmtHour = unixMs ? getMMTHour(unixMs) : null;
  const dateForDay = unixMs ? new Date(unixMs + MMT_OFFSET_MS) : null;

  let content = getContent(data);
  if (content.length > 250) content = content.slice(0, 250) + '...';

  const postType = detectTikTokPostType(data);
  const link = getPostLink(data, handle || normalizeKey(data?.authorMeta?.name));

  posts.push({
    brand_name: brand,
    tiktok_handle: data?.authorMeta?.name || getInputHandle(data),
    content,
    post_type: postType,
    theme: detectTheme(getContent(data)),
    views,
    likes,
    comments,
    shares,
    saves,
    engagement,
    engagement_rate: views > 0 ? ((engagement / views) * 100).toFixed(2) + '%' : '0%',
    postedAt: formatMMT(createTime),
    timestamp: unixMs,
    mmtHour,
    timeBucket: timeBucket(mmtHour),
    dayType: dateForDay ? ([0,6].includes(dateForDay.getUTCDay()) ? 'Weekend' : 'Weekday') : 'Missing Time',
    is_slideshow: postType === 'Slideshow / Photo Post',
    video_duration: toNumber(data?.videoMeta?.duration),
    effect_count: Array.isArray(data.effectStickers) ? data.effectStickers.length : 0,
    link,
    raw_id: postId || '–'
  });
}

// Aggregate per brand.
const statsMap = {};
for (const p of posts) {
  if (!statsMap[p.brand_name]) {
    statsMap[p.brand_name] = {
      brand_name: p.brand_name,
      post_count: 0,
      total_views: 0,
      total_likes: 0,
      total_comments: 0,
      total_shares: 0,
      total_saves: 0,
      total_engagement: 0,
      themes: {},
      post_types: {}
    };
  }
  const s = statsMap[p.brand_name];
  s.post_count++;
  s.total_views      += p.views;
  s.total_likes      += p.likes;
  s.total_comments   += p.comments;
  s.total_shares     += p.shares;
  s.total_saves      += p.saves;
  s.total_engagement += p.engagement;
  s.themes[p.theme]  = (s.themes[p.theme] || 0) + 1;
  s.post_types[p.post_type] = (s.post_types[p.post_type] || 0) + 1;
}

const summary = Object.values(statsMap).map(s => ({
  ...s,
  engagement_rate: s.total_views > 0 ? ((s.total_engagement / s.total_views) * 100).toFixed(2) + '%' : '0%',
  dominant_theme: Object.entries(s.themes).sort((a,b) => b[1]-a[1])[0]?.[0] || 'General',
  dominant_post_type: Object.entries(s.post_types).sort((a,b) => b[1]-a[1])[0]?.[0] || 'Unknown'
})).sort((a,b) => b.total_engagement - a.total_engagement);

// Content type distribution.
const postTypeSummaryMap = {};
for (const p of posts) {
  if (!postTypeSummaryMap[p.post_type]) {
    postTypeSummaryMap[p.post_type] = { post_type: p.post_type, posts: 0, views: 0, engagement: 0, saves: 0 };
  }
  postTypeSummaryMap[p.post_type].posts++;
  postTypeSummaryMap[p.post_type].views += p.views;
  postTypeSummaryMap[p.post_type].engagement += p.engagement;
  postTypeSummaryMap[p.post_type].saves += p.saves;
}
const post_type_summary = Object.values(postTypeSummaryMap).sort((a,b) => b.engagement - a.engagement);

// Brands with profile but zero posts this week.
const inactiveBrands = [...seenBrands]
  .filter(b => !statsMap[b])
  .map(b => ({ brand_name: b, reason: 'No posts this week' }));

// Include hardcoded profiles that were not seen at all.
for (const p of ALL_PROFILES) {
  const brand = brandMap[normalizeKey(p)] || p;
  const wasSeen = seenBrands.has(brand) || seenProfiles.has(normalizeKey(p));
  const alreadyInactive = inactiveBrands.some(x => x.brand_name === brand);
  if (!wasSeen && !alreadyInactive) inactiveBrands.push({ brand_name: brand, reason: 'No data returned' });
}

// Add profile errors from review records.
for (const r of reviewRecords) {
  if (r.reason === 'Profile not found') {
    const exists = inactiveBrands.some(x => x.brand_name === r.brand_name && x.reason === 'Profile not found');
    if (!exists) inactiveBrands.push({ brand_name: r.brand_name, reason: 'Profile not found' });
  }
}

return [{
  json: {
    generated_at: new Date().toISOString(),
    total_raw_records: postsRaw.length,
    total_posts: posts.length,
    brands_detected: summary.length,
    engagement_formula: 'Likes + Comments + Shares + Saves',
    posts,
    summary,
    post_type_summary,
    inactive_brands: inactiveBrands,
    review_records: reviewRecords,
    review_count: reviewRecords.length,
    note: 'TikTok content types are detected as Video, Slideshow / Photo Post, Live, or Unknown / Needs Review. Engagement includes saves.'
  }
}];

// ===================================================
// WEEKLY OBSERVATIONS GENERATOR v3
// Uses TikTok engagement formula: Likes + Comments + Shares + Saves
// ===================================================

const input = $input.first().json;
const posts = input.posts || [];
const summary = input.summary || [];
const inactive_brands = input.inactive_brands || [];
const post_type_summary = input.post_type_summary || [];

function safeNum(n) { return Number(n) || 0; }

const ranked = [...summary].sort((a,b) => safeNum(b.total_engagement) - safeNum(a.total_engagement));
const top = ranked[0];
const bestPost = [...posts].sort((a,b) => safeNum(b.engagement) - safeNum(a.engagement))[0];
const mostShared = [...posts].sort((a,b) => safeNum(b.shares) - safeNum(a.shares))[0];
const mostSaved = [...posts].sort((a,b) => safeNum(b.saves) - safeNum(a.saves))[0];
const mostCommented = [...posts].sort((a,b) => safeNum(b.comments) - safeNum(a.comments))[0];

const timeCounts = {};
posts.forEach(p => { timeCounts[p.timeBucket] = (timeCounts[p.timeBucket] || 0) + 1; });
const peakTime = Object.entries(timeCounts).sort((a,b) => b[1]-a[1])[0];

const weekendPosts = posts.filter(p => p.dayType === 'Weekend').length;
const weekdayPosts = posts.filter(p => p.dayType === 'Weekday').length;

const themeCounts = {};
posts.forEach(p => { themeCounts[p.theme] = (themeCounts[p.theme] || 0) + 1; });
const topTheme = Object.entries(themeCounts).sort((a,b) => b[1]-a[1])[0];

const dayCounts = {};
posts.forEach(p => {
  if (!p.timestamp) return;
  const dayLabel = new Date(p.timestamp + 390*60*1000)
    .toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: '2-digit', month: 'short' });
  dayCounts[dayLabel] = (dayCounts[dayLabel] || 0) + 1;
});
const busiestDay = Object.entries(dayCounts).sort((a,b) => b[1]-a[1])[0];

const topPostType = post_type_summary[0];

const observations = [
  top ? `<strong>${top.brand_name}</strong> led this week with ${safeNum(top.total_engagement).toLocaleString()} total engagement across ${safeNum(top.post_count)} post(s). Engagement formula: Likes + Comments + Shares + Saves.` : null,

  bestPost ? `Best single post came from <strong>${bestPost.brand_name}</strong> (${safeNum(bestPost.views).toLocaleString()} views, ${safeNum(bestPost.engagement).toLocaleString()} engagement) — type: ${bestPost.post_type}, theme: ${bestPost.theme}.` : null,

  topPostType ? `Most effective content type this week: <strong>${topPostType.post_type}</strong> (${safeNum(topPostType.posts)} post(s), ${safeNum(topPostType.engagement).toLocaleString()} engagement).` : null,

  mostShared && safeNum(mostShared.shares) > 0 ? `<strong>${mostShared.brand_name}</strong> had the most shares (${safeNum(mostShared.shares)}), showing forwarding/viral potential.` : null,

  mostSaved && safeNum(mostSaved.saves) > 0 ? `<strong>${mostSaved.brand_name}</strong> had the most saves (${safeNum(mostSaved.saves)}), showing content people may want to revisit later.` : null,

  mostCommented && safeNum(mostCommented.comments) > 0 ? `<strong>${mostCommented.brand_name}</strong> generated the most comments (${safeNum(mostCommented.comments)}), the strongest conversation signal.` : null,

  peakTime ? `Most active posting time: <strong>${peakTime[0]}</strong> (${peakTime[1]} post${peakTime[1] > 1 ? 's' : ''}). ${weekendPosts} weekend posts vs ${weekdayPosts} weekday posts this week.` : null,

  topTheme ? `Most common content theme across all brands: <strong>${topTheme[0]}</strong> (${topTheme[1]} post${topTheme[1] > 1 ? 's' : ''}).` : null,

  busiestDay ? `Heaviest posting day: <strong>${busiestDay[0]}</strong> (${busiestDay[1]} posts).` : null,

  inactive_brands.length > 0 ? `${inactive_brands.length} brand(s) returned no active posts/data this week: ${inactive_brands.map(b => `${b.brand_name} (${b.reason})`).join(', ')}.` : null
].filter(Boolean);

return [{ json: { ...input, observations } }];
